/* PintsNow app part: PN.put/link/s, constants, $, deep-link params, hook fan-out mods() + runWave(). Moved from app.js without change (W2 step 1). Shared state: PN.s (app-core.js). */
(function () {
  "use strict";
  // <split:core> generated by scripts/split/move.mjs — do not edit (PN.put, PN.link, PN.s; a field start value may be edited here)
  var PN = window.PN, links = [];
  PN.put = function (o) { for (var k in o) PN[k] = o[k]; for (var i = 0; i < links.length; i++) links[i](); };
  PN.link = function (fn) { links.push(fn); fn(); };
  PN.s = {
    pendingFocus: null,
    pendingAct: null,   // v27 🔔 push buttons: "coming" (🍺 Kommer!) | "skal" (🍻 Skåla) for the focused pin
    busy: false,
    modsSkip: null,
    modsWave: null,
    sheetCur: null,
    client: null,
    authed: false,
    firstLoadDone: false,
    bgCall: false,   // true while WARM's background prefetch calls rpcNet (see WARM.setRaw)   // arguments of type jsonb: an object may go in the bundle too
    bq: [],
    authedAt: 0,
    pollSlow: false,
    slowLaneAt: 0,
    pollOn: false,
    lastUiClick: 0,
    publicOn: false,
    beers: [],
    checkins: [],
    lastLoc: null,          // last known own location {lat, lng} (locate or own beer tap)
    movedState: false,
    flyttHiddenAt: 0,
    pubTimer: null,
  };
  // </split:core>
  // <split:imports> generated by scripts/split/move.mjs — do not edit
  function bgRun() { return PN.bgRun.apply(null, arguments); }
  PN.put({ mods: mods, runWave: runWave });
  // </split:imports>
  var U = window.U, I = window.I18N, t = I.t;
  PN.put({ U: U, I: I, t: t });   // <split:put/>
  var CFG = window.OLNU_CONFIG || {};
  PN.put({ CFG: CFG });   // <split:put/>
  // No Supabase keys yet → "coming soon" mode: real map + real bars, no beers, ÖL! disabled.
  var LIVE = !!(CFG.SUPABASE_URL && CFG.SUPABASE_ANON_KEY);
  PN.put({ LIVE: LIVE });   // <split:put/>
  var PUSH_ON = LIVE && !!CFG.VAPID_PUBLIC_KEY;
  PN.put({ PUSH_ON: PUSH_ON });   // <split:put/>

  var SWEDEN = [[55.0, 10.9], [69.1, 24.2]];
  var MAX_BOUNDS = [[53.3, 7.5], [70.8, 27.8]];
  var POLL_MS = 30000, POLL_SLOW_MS = 60000, IDLE_MS = 180000, HEAT_MS = 60000, RPC_TIMEOUT_MS = 15000;
  PN.put({ POLL_MS: POLL_MS, POLL_SLOW_MS: POLL_SLOW_MS, IDLE_MS: IDLE_MS, HEAT_MS: HEAT_MS, RPC_TIMEOUT_MS: RPC_TIMEOUT_MS });   // <split:put/>
  var LUDVIKA = [60.1496, 15.1878], START_ZOOM = 14;
  PN.put({ LUDVIKA: LUDVIKA, START_ZOOM: START_ZOOM });   // <split:put/>
  var HOT_ZOOM = 11, BAR_ZOOM = 13, MAX_PLAIN_BARS = 300;
  PN.put({ HOT_ZOOM: HOT_ZOOM, BAR_ZOOM: BAR_ZOOM, MAX_PLAIN_BARS: MAX_PLAIN_BARS });   // <split:put/>

  var $ = function (id) { return document.getElementById(id); };
  PN.put({ $: $ });   // <split:put/>
  // v9: hooks into js/social.js + js/extras.js. Returns the joined HTML of string results. A broken module never breaks the app.
  function mods(fn, a, b, c) {
    var out = "";
    PN.hookList().forEach(function (m) {
      if (!m || typeof m[fn] !== "function" || (PN.s.modsSkip && PN.s.modsSkip.indexOf(m) >= 0)) return;
      if (PN.s.modsWave && fn === "onPoll") { PN.s.modsWave.push(m); return; }   // ⚡ SPEED: runWave() calls it
      try { var r = m[fn](a, b, c); if (typeof r === "string") out += r; } catch (e) { try { console.warn("olnu " + fn, e); } catch (x) {} }
    });
    return out;
  }
  // ⚡ SPEED: the onPoll fan-out in waves (5 modules, then the next 5 after 250 ms …): ~15 module RPCs no longer start in
  // the same tick (they queued for 8–16 s on phones after a resume). A newer poll or a hidden page stops the old wave.
  var waveSeq = 0, WAVE_N = 5, WAVE_MS = 250;
  function runWave(list, arg) {
    var seq = ++waveSeq, i = 0;
    (function step() {
      if (seq !== waveSeq || document.hidden) return;
      bgRun(function () { list.slice(i, i + WAVE_N).forEach(function (m) { try { m.onPoll(arg); } catch (e) { try { console.warn("olnu onPoll", e); } catch (x) {} } }); });   // fixP N-01
      i += WAVE_N; if (i < list.length) setTimeout(step, WAVE_MS);
    })();
  }   // review2: shared slow lane (see onPoll)

  /* ---------- Deep links ---------- */
  // QA #15: one short toast for a link whose target is gone (social.js uses it too). Rank 2 (urgent), so poll news does not push it out.
  I.add({ sv: { linkGone: "🔗 Hittade inte den länken – den har nog gått ut" }, en: { linkGone: "🔗 Could not find that link – it has probably expired" } });
  var params = new URLSearchParams(location.search);
  var joinCode = params.get("join");
  PN.put({ joinCode: joinCode });   // <split:put/>
  var focusId = params.get("focus");
  var invited = params.has("invite");
  PN.put({ invited: invited });   // <split:put/>
  var chatId = params.get("chat"), sosAt = params.get("sos");   // v9 push links
  PN.put({ chatId: chatId, sosAt: sosAt });   // <split:put/>
  var rallyId = params.get("rally"), rallyAns = params.get("answer");
  PN.put({ rallyId: rallyId, rallyAns: rallyAns });   // <split:put/>
  var barLink = params.get("bar");   // v12 krogtips / takeover push: open that bar
  PN.put({ barLink: barLink });   // <split:put/>
  if (focusId) PN.s.pendingFocus = focusId;
  if (focusId && /^(coming|skal)$/.test(params.get("act") || "")) PN.s.pendingAct = params.get("act");
  params.delete("act"); params.delete("reply");
  if (["join", "focus", "chat", "sos", "bar", "rally"].some(function (k) { return params.has(k); }) || invited || rallyAns) {   // QA #15: also an empty ?join=
    params.delete("join"); params.delete("focus"); params.delete("invite"); params.delete("chat"); params.delete("sos"); params.delete("bar");
    params.delete("rally"); params.delete("answer");   // a reload must not answer again
    var qs = params.toString();
    try { history.replaceState(null, "", location.pathname + (qs ? "?" + qs : "") + location.hash); } catch (e) {}
  }
})();
